import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for matrix multiplication with bias
mm_bias_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_bias_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int batch_size,
    int in_features,
    int out_features
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_features;
    if (idx < total) {
        int i = idx / out_features;        // batch index
        int j = idx % out_features;        // out_feature index

        float val = bias[j];
        for (int k = 0; k < in_features; k++) {
            val += x[i * in_features + k] * weight[j * in_features + k];
        }
        out[idx] = val;
    }
}

torch::Tensor matmul_bias_cuda(torch::Tensor x,
                               torch::Tensor weight,
                               torch::Tensor bias) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = weight.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());
    int total = batch_size * out_features;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    matmul_bias_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return out;
}
"""

mm_bias_cpp_source = "torch::Tensor matmul_bias_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias);"

mm_bias = load_inline(
    name="mm_bias",
    cpp_sources=mm_bias_cpp_source,
    cuda_sources=mm_bias_source,
    functions=["matmul_bias_cuda"],
    verbose=False
)

# Custom CUDA kernel for Swish activation + scaling
swish_scale_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void swish_scale_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    float scale,
    int size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = inp[idx];
        float sig_val = 1.0f / (1.0f + expf(-val));
        out[idx] = val * sig_val * scale;
    }
}

torch::Tensor swish_scale_cuda(torch::Tensor inp, float scale) {
    auto out = torch::zeros_like(inp);
    int size = inp.numel();

    int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;

    swish_scale_kernel<<<grid_size, block_size>>>(
        inp.data_ptr<float>(),
        out.data_ptr<float>(),
        scale,
        size
    );

    return out;
}
"""

swish_scale_cpp_source = "torch::Tensor swish_scale_cuda(torch::Tensor inp, float scale);"

swish_scale = load_inline(
    name="swish_scale",
    cpp_sources=swish_scale_cpp_source,
    cuda_sources=swish_scale_source,
    functions=["swish_scale_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor):
        super().__init__()
        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))
        nn.init.xavier_uniform_(self.weight)
        nn.init.zeros_(self.bias)
        self.scaling_factor = scaling_factor

    def forward(self, x):
        x = mm_bias.matmul_bias_cuda(x, self.weight, self.bias)
        x = swish_scale.swish_scale_cuda(x, self.scaling_factor)
        return x
